import json


def respond(request_id, outcome):
    """Return the JSON-RPC response (without _meta) a server sends to one request."""
    kind = outcome[0]
    if kind == "unknown_method":
        return {"jsonrpc": "2.0", "id": request_id,
                "error": {"code": -32601, "message": "Method not found", "data": outcome[1]}}
    if kind == "arguments_not_object":
        return {"jsonrpc": "2.0", "id": request_id,
                "error": {"code": -32602, "message": "Invalid params"}}
    if kind == "tool_failed":
        result = {"content": [{"type": "text", "text": outcome[1]}],
                  "isError": True, "resultType": "complete"}
        return {"jsonrpc": "2.0", "id": request_id, "result": result}
    data = outcome[1]
    result = {"content": [{"type": "text", "text": json.dumps(data)}],
              "structuredContent": data, "isError": False, "resultType": "complete"}
    return {"jsonrpc": "2.0", "id": request_id, "result": result}

